import{_ as o,o as e,c as t,a5 as d}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"설치","description":"","frontmatter":{"title":"설치","order":1},"headers":[],"relativePath":"ko/2.4/konadotnet/install_konadotnet.md","filePath":"ko/2.4/konadotnet/install_konadotnet.md","lastUpdated":1788455378000}'),l={name:"ko/2.4/konadotnet/install_konadotnet.md"};function n(i,a,r,s,c,h){return e(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="설치" tabindex="-1">설치 <a class="header-anchor" href="#설치" aria-label="Permalink to &quot;설치&quot;">​</a></h1><h2 id="기본-의존성" tabindex="-1">기본 의존성 <a class="header-anchor" href="#기본-의존성" aria-label="Permalink to &quot;기본 의존성&quot;">​</a></h2><ol><li>Konado 플러그인 설치(필수)</li><li>C#을 지원하는 Godot 버전(Godot 4.6 이상 권장)</li><li>프로젝트를 Godot .NET 에디터로 열어야 합니다. 일반 Godot 에디터는 C# 애드온 스크립트를 컴파일하거나 로드할 수 없습니다.</li></ol><h2 id="설치-단계" tabindex="-1">설치 단계 <a class="header-anchor" href="#설치-단계" aria-label="Permalink to &quot;설치 단계&quot;">​</a></h2><ol><li>konadotnet 플러그인을 Godot 프로젝트의 <code>addons</code> 디렉터리에 압축 해제합니다</li><li>기본 <code>addons/konado</code> 플러그인도 프로젝트에 있는지 확인합니다</li><li>Godot 에디터에서 <code>Project -&gt; Project Settings -&gt; Plugins</code>로 이동해 먼저 <code>Konado</code>를 활성화합니다</li><li>C# 프로젝트를 빌드하고 MSBuild 오류가 없는지 확인합니다</li><li><code>Konadotnet</code> 플러그인을 활성화합니다</li><li>프로젝트를 다시 열어 자동 로드 노드와 C# 스크립트 상태를 갱신합니다</li></ol><h2 id="처음-활성화할-때의-흔한-오류" tabindex="-1">처음 활성화할 때의 흔한 오류 <a class="header-anchor" href="#처음-활성화할-때의-흔한-오류" aria-label="Permalink to &quot;처음 활성화할 때의 흔한 오류&quot;">​</a></h2><p>C# 프로젝트를 아직 빌드하지 않았다면 다음 오류가 나타날 수 있습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to load addon script from path: &#39;res://addons/konadotnet/Konadotnet.cs&#39;.</span></span></code></pre></div><p>Godot .NET 에디터에서 프로젝트를 빌드한 뒤 다시 열고 플러그인을 활성화하세요.</p><h2 id="장면-요구-사항" tabindex="-1">장면 요구 사항 <a class="header-anchor" href="#장면-요구-사항" aria-label="Permalink to &quot;장면 요구 사항&quot;">​</a></h2><p><code>DialogueManagerAPI</code>를 사용하려면 현재 장면에 <code>KND_DialogueManager</code> 노드가 필요합니다. Konadotnet은 다음 일반적인 노드 이름도 지원합니다.</p><ul><li><code>DialogManager</code></li><li><code>DialogueManager</code></li><li><code>KonadoDialogueManager</code></li></ul><p>대화 관리자가 여러 개라면 수동으로 바인딩하세요.</p>',13)])])}const _=o(l,[["render",n]]);export{u as __pageData,_ as default};
